#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdint.h&gt;
#include &lt;string.h&gt;
#include &lt;time.h&gt;

#define DISPLAY_W 64
#define DISPLAY_H 32

typedef struct {
    uint8_t  memory[4096];
    uint8_t  V[16];
    uint16_t I;
    uint16_t pc;
    uint16_t stack[16];
    uint8_t  sp;
    uint8_t  display[DISPLAY_W * DISPLAY_H];
    int      draw_flag;
} Chip8;

static const uint8_t fontset[80] = {
    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
    0x20, 0x60, 0x20, 0x20, 0x70, // 1
    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
    0x90, 0x90, 0xF0, 0x10, 0x10, // 4
    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
    0xF0, 0x80, 0xF0, 0x80, 0x80, // F
};

void chip8_init(Chip8 *c) {
    memset(c, 0, sizeof(Chip8));
    c-&gt;pc = 0x200;
    memcpy(c-&gt;memory + 0x050, fontset, sizeof(fontset));
}

int chip8_load_rom(Chip8 *c, const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open ROM: %s\n", path); return 0; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    rewind(f);
    fread(c-&gt;memory + 0x200, 1, (size_t)size, f);
    fclose(f);
    return 1;
}

void chip8_render(Chip8 *c) {
    printf("\x1b[H\x1b[2J");
    for (int row = 0; row &lt; DISPLAY_H; row++) {
        for (int col = 0; col &lt; DISPLAY_W; col++) {
            putchar(c-&gt;display[row * DISPLAY_W + col] ? 0xE2 : ' '); // see note below
        }
        putchar('\n');
    }
}

void chip8_cycle(Chip8 *c) {
    uint16_t opcode = (c-&gt;memory[c-&gt;pc] &lt;&lt; 8) | c-&gt;memory[c-&gt;pc + 1];
    c-&gt;pc += 2;

    uint16_t nnn = opcode & 0x0FFF;
    uint8_t  n   = opcode & 0x000F;
    uint8_t  x   = (opcode & 0x0F00) &gt;&gt; 8;
    uint8_t  y   = (opcode & 0x00F0) &gt;&gt; 4;
    uint8_t  kk  = opcode & 0x00FF;

    switch (opcode & 0xF000) {
        case 0x0000:
            if (opcode == 0x00E0) {
                memset(c-&gt;display, 0, sizeof(c-&gt;display));
                c-&gt;draw_flag = 1;
            } else if (opcode == 0x00EE) {
                c-&gt;pc = c-&gt;stack[--c-&gt;sp];
            } else {
                fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        case 0x1000: c-&gt;pc = nnn; break;
        case 0x2000: c-&gt;stack[c-&gt;sp++] = c-&gt;pc; c-&gt;pc = nnn; break;
        case 0x3000: if (c-&gt;V[x] == kk)      c-&gt;pc += 2; break;
        case 0x4000: if (c-&gt;V[x] != kk)      c-&gt;pc += 2; break;
        case 0x5000: if (c-&gt;V[x] == c-&gt;V[y]) c-&gt;pc += 2; break;
        case 0x9000: if (c-&gt;V[x] != c-&gt;V[y]) c-&gt;pc += 2; break;
        case 0x6000: c-&gt;V[x] = kk; break;
        case 0x7000: c-&gt;V[x] += kk; break;

        case 0x8000: {
            switch (n) {
                case 0x0: c-&gt;V[x] = c-&gt;V[y]; break;
                case 0x1: c-&gt;V[x] |= c-&gt;V[y]; break;
                case 0x2: c-&gt;V[x] &= c-&gt;V[y]; break;
                case 0x3: c-&gt;V[x] ^= c-&gt;V[y]; break;
                case 0x4: {
                    uint16_t sum = c-&gt;V[x] + c-&gt;V[y];
                    c-&gt;V[0xF] = sum &gt; 0xFF;
                    c-&gt;V[x] = (uint8_t)sum;
                    break;
                }
                case 0x5: {
                    uint8_t borrow = c-&gt;V[x] &gt; c-&gt;V[y];
                    c-&gt;V[x] -= c-&gt;V[y];
                    c-&gt;V[0xF] = borrow;
                    break;
                }
                case 0x6: {
                    uint8_t lsb = c-&gt;V[x] & 0x1;
                    c-&gt;V[x] &gt;&gt;= 1;
                    c-&gt;V[0xF] = lsb;
                    break;
                }
                case 0x7: {
                    uint8_t borrow = c-&gt;V[y] &gt; c-&gt;V[x];
                    c-&gt;V[x] = c-&gt;V[y] - c-&gt;V[x];
                    c-&gt;V[0xF] = borrow;
                    break;
                }
                case 0xE: {
                    uint8_t msb = (c-&gt;V[x] &gt;&gt; 7) & 0x1;
                    c-&gt;V[x] &lt;&lt;= 1;
                    c-&gt;V[0xF] = msb;
                    break;
                }
                default:
                    fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;
        }

        case 0xA000: c-&gt;I = nnn; break;
        case 0xB000: c-&gt;pc = nnn + c-&gt;V[0]; break;
        case 0xC000: c-&gt;V[x] = (rand() % 256) & kk; break;

        case 0xD000: { // DXYN: draw sprite
            uint8_t vx = c-&gt;V[x] % DISPLAY_W;
            uint8_t vy = c-&gt;V[y] % DISPLAY_H;
            c-&gt;V[0xF] = 0;

            for (int row = 0; row &lt; n; row++) {
                uint8_t sprite_byte = c-&gt;memory[c-&gt;I + row];
                for (int bit = 0; bit &lt; 8; bit++) {
                    if (!(sprite_byte & (0x80 &gt;&gt; bit))) continue;

                    int px = (vx + bit) % DISPLAY_W;
                    int py = (vy + row) % DISPLAY_H;
                    int idx = py * DISPLAY_W + px;

                    if (c-&gt;display[idx]) c-&gt;V[0xF] = 1; // collision
                    c-&gt;display[idx] ^= 1;
                }
            }
            c-&gt;draw_flag = 1;
            break;
        }

        case 0xF000: {
            if (kk == 0x29) { // FX29: LD F, Vx
                c-&gt;I = 0x050 + (c-&gt;V[x] * 5);
            } else {
                fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;
        }

        default:
            fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
    }
}

int main(int argc, char **argv) {
    srand((unsigned)time(NULL));

    if (argc &lt; 2) {
        fprintf(stderr, "Usage: %s rom.ch8\n", argv[0]);
        return 1;
    }

    Chip8 chip8;
    chip8_init(&chip8);
    if (!chip8_load_rom(&chip8, argv[1])) return 1;

    for (int i = 0; i &lt; 500; i++) {
        chip8_cycle(&chip8);
        if (chip8.draw_flag) {
            chip8_render(&chip8);
            chip8.draw_flag = 0;
        }
    }
    return 0;
}

