    if (!f) { fprintf(stderr, "Cannot open ROM: %s\n", path); return 0; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    rewind(f);
    fread(c-&gt;memory + 0x200, 1, (size_t)size, f);
    fclose(f);
    return 1;
}

void chip8_cycle(Chip8 *c) {
    uint16_t opcode = (c-&gt;memory[c-&gt;pc] &lt;&lt; 8) | c-&gt;memory[c-&gt;pc + 1];
    c-&gt;pc += 2;

    uint16_t nnn = opcode & 0x0FFF;
    uint8_t  n   = opcode & 0x000F;
    uint8_t  x   = (opcode & 0x0F00) &gt;&gt; 8;
    uint8_t  y   = (opcode & 0x00F0) &gt;&gt; 4;
    uint8_t  kk  = opcode & 0x00FF;

    switch (opcode & 0xF000) {
        case 0x0000:
            if (opcode == 0x00E0) {
                printf("[CLS]\n");
            } else if (opcode == 0x00EE) { // RET
                c-&gt;pc = c-&gt;stack[--c-&gt;sp];
            } else {
                fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        case 0x1000: c-&gt;pc = nnn; break; // JP addr

        case 0x2000: // CALL addr
            c-&gt;stack[c-&gt;sp++] = c-&gt;pc;
            c-&gt;pc = nnn;
            break;

        case 0x3000: if (c-&gt;V[x] == kk)      c-&gt;pc += 2; break; // SE Vx, byte
        case 0x4000: if (c-&gt;V[x] != kk)      c-&gt;pc += 2; break; // SNE Vx, byte
        case 0x5000: if (c-&gt;V[x] == c-&gt;V[y]) c-&gt;pc += 2; break; // SE Vx, Vy
        case 0x9000: if (c-&gt;V[x] != c-&gt;V[y]) c-&gt;pc += 2; break; // SNE Vx, Vy

        case 0x6000: c-&gt;V[x] = kk; break;        // LD Vx, byte
        case 0x7000: c-&gt;V[x] += kk; break;       // ADD Vx, byte (no carry)

        case 0x8000: {
            switch (n) {
                case 0x0: c-&gt;V[x] = c-&gt;V[y]; break;
                case 0x1: c-&gt;V[x] |= c-&gt;V[y]; break;
                case 0x2: c-&gt;V[x] &= c-&gt;V[y]; break;
                case 0x3: c-&gt;V[x] ^= c-&gt;V[y]; break;
                case 0x4: {
                    uint16_t sum = c-&gt;V[x] + c-&gt;V[y];
                    c-&gt;V[0xF] = sum &gt; 0xFF;
                    c-&gt;V[x] = (uint8_t)sum;
                    break;
                }
                case 0x5: {
                    uint8_t borrow = c-&gt;V[x] &gt; c-&gt;V[y];
                    c-&gt;V[x] -= c-&gt;V[y];
                    c-&gt;V[0xF] = borrow;
                    break;
                }
                case 0x6: {
                    uint8_t lsb = c-&gt;V[x] & 0x1;
                    c-&gt;V[x] &gt;&gt;= 1;
                    c-&gt;V[0xF] = lsb;
                    break;
                }
                case 0x7: {
                    uint8_t borrow = c-&gt;V[y] &gt; c-&gt;V[x];
                    c-&gt;V[x] = c-&gt;V[y] - c-&gt;V[x];
                    c-&gt;V[0xF] = borrow;
                    break;
                }
                case 0xE: {
                    uint8_t msb = (c-&gt;V[x] &gt;&gt; 7) & 0x1;
                    c-&gt;V[x] &lt;&lt;= 1;
                    c-&gt;V[0xF] = msb;
                    break;
                }
                default:
                    fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;
        }

        case 0xA000: c-&gt;I = nnn; break;              // LD I, addr
        case 0xB000: c-&gt;pc = nnn + c-&gt;V[0]; break;    // JP V0, addr
        case 0xC000: c-&gt;V[x] = (rand() % 256) & kk; break; // RND Vx, byte

        default:
            fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
    }
}

int main(int argc, char **argv) {
    srand((unsigned)time(NULL));

    Chip8 chip8;
    chip8_init(&chip8);

    if (argc &gt;= 2) {
        if (!chip8_load_rom(&chip8, argv[1])) return 1;
    } else {
        uint8_t test_rom[] = {
            0x60, 0x05,
            0x30, 0x00,
            0x12, 0x08,
            0x22, 0x0C,
            0x70, 0xFF,
            0x12, 0x02,
            0x61, 0x42,
            0x00, 0xEE,
        };
        memcpy(chip8.memory + 0x200, test_rom, sizeof(test_rom));
    }

    for (int i = 0; i &lt; 20; i++) {
        printf("PC=0x%03X V0=%d V1=%d\n", chip8.pc, chip8.V[0], chip8.V[1]);
        chip8_cycle(&chip8);
    }
    return 0;
}

