void chip8_render(Chip8 *c) {
    printf("\x1b[H\x1b[2J");
    for (int row = 0; row &lt; DISPLAY_H; row++) {
        for (int col = 0; col &lt; DISPLAY_W; col++) {
            fputs(c-&gt;display[row * DISPLAY_W + col] ? "\xE2\x96\x88" : " ", stdout);
        }
        putchar('\n');
    }
}

