            switch (n) {
                case 0x0: c-&gt;V[x] = c-&gt;V[y]; break;
                case 0x1: c-&gt;V[x] |= c-&gt;V[y]; break;
                case 0x2: c-&gt;V[x] &= c-&gt;V[y]; break;
                case 0x3: c-&gt;V[x] ^= c-&gt;V[y]; break;
                case 0x4: { uint16_t s = c-&gt;V[x] + c-&gt;V[y]; c-&gt;V[0xF] = s &gt; 0xFF; c-&gt;V[x] = (uint8_t)s; break; }
                case 0x5: { uint8_t b = c-&gt;V[x] &gt; c-&gt;V[y]; c-&gt;V[x] -= c-&gt;V[y]; c-&gt;V[0xF] = b; break; }
                case 0x6: { uint8_t b = c-&gt;V[x] & 1; c-&gt;V[x] &gt;&gt;= 1; c-&gt;V[0xF] = b; break; }
                case 0x7: { uint8_t b = c-&gt;V[y] &gt; c-&gt;V[x]; c-&gt;V[x] = c-&gt;V[y] - c-&gt;V[x]; c-&gt;V[0xF] = b; break; }
                case 0xE: { uint8_t b = (c-&gt;V[x] &gt;&gt; 7) & 1; c-&gt;V[x] &lt;&lt;= 1; c-&gt;V[0xF] = b; break; }
                default: fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        case 0xA000: c-&gt;I = nnn; break;
        case 0xB000: c-&gt;pc = nnn + c-&gt;V[0]; break;
        case 0xC000: c-&gt;V[x] = (rand() % 256) & kk; break;

        case 0xD000: {
            uint8_t vx = c-&gt;V[x] % DISPLAY_W, vy = c-&gt;V[y] % DISPLAY_H;
            c-&gt;V[0xF] = 0;
            for (int row = 0; row &lt; n; row++) {
                uint8_t sb = c-&gt;memory[c-&gt;I + row];
                for (int bit = 0; bit &lt; 8; bit++) {
                    if (!(sb & (0x80 &gt;&gt; bit))) continue;
                    int px = (vx + bit) % DISPLAY_W, py = (vy + row) % DISPLAY_H;
                    int idx = py * DISPLAY_W + px;
                    if (c-&gt;display[idx]) c-&gt;V[0xF] = 1;
                    c-&gt;display[idx] ^= 1;
                }
            }
            c-&gt;draw_flag = 1;
            break;
        }

        case 0xE000:
            if (kk == 0x9E) { if (c-&gt;keypad[c-&gt;V[x]])  c-&gt;pc += 2; }
            else if (kk == 0xA1) { if (!c-&gt;keypad[c-&gt;V[x]]) c-&gt;pc += 2; }
            else fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            break;

        case 0xF000:
            switch (kk) {
                case 0x07: c-&gt;V[x] = c-&gt;delay_timer; break;
                case 0x15: c-&gt;delay_timer = c-&gt;V[x]; break;
                case 0x18: c-&gt;sound_timer = c-&gt;V[x]; break;
                case 0x29: c-&gt;I = 0x050 + (c-&gt;V[x] * 5); break;
                case 0x0A: {
                    int pressed = -1;
                    for (int k = 0; k &lt; 16; k++) if (c-&gt;keypad[k]) { pressed = k; break; }
                    if (pressed &lt; 0) c-&gt;pc -= 2; // block: repeat this instruction
                    else c-&gt;V[x] = (uint8_t)pressed;
                    break;
                }
                default: fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        default:
            fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
    }
}

int main(int argc, char **argv) {
    if (argc &lt; 2) { fprintf(stderr, "Usage: %s rom.ch8\n", argv[0]); return 1; }

    srand((unsigned)time(NULL));
    enable_raw_mode();

    Chip8 chip8;
    chip8_init(&chip8);
    if (!chip8_load_rom(&chip8, argv[1])) return 1;

    for (;;) {
        memset(chip8.keypad, 0, sizeof(chip8.keypad));
        int ch;
        while ((ch = getchar()) != EOF) {
            int k = map_key((char)ch);
            if (k &gt;= 0) chip8.keypad[k] = 1;
            if (ch == 27) { disable_raw_mode(); return 0; } // ESC to quit
        }

        for (int i = 0; i &lt; 9; i++) chip8_cycle(&chip8);

        if (chip8.delay_timer &gt; 0) chip8.delay_timer--;
        if (chip8.sound_timer &gt; 0) chip8.sound_timer--;

        if (chip8.draw_flag) { chip8_render(&chip8); chip8.draw_flag = 0; }

        usleep(16667);
    }
}

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdint.h&gt;
#include &lt;string.h&gt;
#include &lt;time.h&gt;
#include &lt;unistd.h&gt;
#include &lt;termios.h&gt;
#include &lt;fcntl.h&gt;

#define DISPLAY_W 64
#define DISPLAY_H 32

typedef struct {
    uint8_t  memory[4096];
    uint8_t  V[16];
    uint16_t I;
    uint16_t pc;
    uint16_t stack[16];
    uint8_t  sp;
    uint8_t  display[DISPLAY_W * DISPLAY_H];
    int      draw_flag;
    uint8_t  delay_timer;
    uint8_t  sound_timer;
    uint8_t  keypad[16];
} Chip8;

static const uint8_t fontset[80] = {
    0xF0,0x90,0x90,0x90,0xF0, 0x20,0x60,0x20,0x20,0x70,
    0xF0,0x10,0xF0,0x80,0xF0, 0xF0,0x10,0xF0,0x10,0xF0,
    0x90,0x90,0xF0,0x10,0x10, 0xF0,0x80,0xF0,0x10,0xF0,
    0xF0,0x80,0xF0,0x90,0xF0, 0xF0,0x10,0x20,0x40,0x40,
    0xF0,0x90,0xF0,0x90,0xF0, 0xF0,0x90,0xF0,0x10,0xF0,
    0xF0,0x90,0xF0,0x90,0x90, 0xE0,0x90,0xE0,0x90,0xE0,
    0xF0,0x80,0x80,0x80,0xF0, 0xE0,0x90,0x90,0x90,0xE0,
    0xF0,0x80,0xF0,0x80,0xF0, 0xF0,0x80,0xF0,0x80,0x80,
};

static struct termios orig_termios;

void disable_raw_mode(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

void enable_raw_mode(void) {
    tcgetattr(STDIN_FILENO, &orig_termios);
    atexit(disable_raw_mode);
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    tcsetattr(STDIN_FILENO, TCSANOW, &raw);
    fcntl(STDIN_FILENO, F_SETFL, fcntl(STDIN_FILENO, F_GETFL) | O_NONBLOCK);
}

int map_key(char ch) {
    switch (ch) {
        case '1': return 0x1; case '2': return 0x2;
        case '3': return 0x3; case '4': return 0xC;
        case 'q': return 0x4; case 'w': return 0x5;
        case 'e': return 0x6; case 'r': return 0xD;
        case 'a': return 0x7; case 's': return 0x8;
        case 'd': return 0x9; case 'f': return 0xE;
        case 'z': return 0xA; case 'x': return 0x0;
        case 'c': return 0xB; case 'v': return 0xF;
        default:  return -1;
    }
}

void chip8_init(Chip8 *c) {
    memset(c, 0, sizeof(Chip8));
    c-&gt;pc = 0x200;
    memcpy(c-&gt;memory + 0x050, fontset, sizeof(fontset));
}

int chip8_load_rom(Chip8 *c, const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open ROM: %s\n", path); return 0; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    rewind(f);
    fread(c-&gt;memory + 0x200, 1, (size_t)size, f);
    fclose(f);
    return 1;
}

void chip8_render(Chip8 *c) {
    printf("\x1b[H\x1b[2J");
    for (int row = 0; row &lt; DISPLAY_H; row++) {
        for (int col = 0; col &lt; DISPLAY_W; col++) {
            fputs(c-&gt;display[row * DISPLAY_W + col] ? "\xE2\x96\x88" : " ", stdout);
        }
        putchar('\n');
    }
}

void chip8_cycle(Chip8 *c) {
    uint16_t opcode = (c-&gt;memory[c-&gt;pc] &lt;&lt; 8) | c-&gt;memory[c-&gt;pc + 1];
    c-&gt;pc += 2;

    uint16_t nnn = opcode & 0x0FFF;
    uint8_t  n   = opcode & 0x000F;
    uint8_t  x   = (opcode & 0x0F00) &gt;&gt; 8;
    uint8_t  y   = (opcode & 0x00F0) &gt;&gt; 4;
    uint8_t  kk  = opcode & 0x00FF;

    switch (opcode & 0xF000) {
        case 0x0000:
            if (opcode == 0x00E0) { memset(c-&gt;display, 0, sizeof(c-&gt;display)); c-&gt;draw_flag = 1; }
            else if (opcode == 0x00EE) { c-&gt;pc = c-&gt;stack[--c-&gt;sp]; }
            else fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            break;
        case 0x1000: c-&gt;pc = nnn; break;
        case 0x2000: c-&gt;stack[c-&gt;sp++] = c-&gt;pc; c-&gt;pc = nnn; break;
        case 0x3000: if (c-&gt;V[x] == kk)      c-&gt;pc += 2; break;
        case 0x4000: if (c-&gt;V[x] != kk)      c-&gt;pc += 2; break;
        case 0x5000: if (c-&gt;V[x] == c-&gt;V[y]) c-&gt;pc += 2; break;
        case 0x9000: if (c-&gt;V[x] != c-&gt;V[y]) c-&gt;pc += 2; break;
        case 0x6000: c-&gt;V[x] = kk; break;
        case 0x7000: c-&gt;V[x] += kk; break;

        case 0x8000:
            switch (n) {
                case 0x0: c-&gt;V[x] = c-&gt;V[y]; break;
                case 0x1: c-&gt;V[x] |= c-&gt;V[y]; break;
                case 0x2: c-&gt;V[x] &= c-&gt;V[y]; break;
                case 0x3: c-&gt;V[x] ^= c-&gt;V[y]; break;
                case 0x4: { uint16_t s = c-&gt;V[x] + c-&gt;V[y]; c-&gt;V[0xF] = s &gt; 0xFF; c-&gt;V[x] = (uint8_t)s; break; }
                case 0x5: { uint8_t b = c-&gt;V[x] &gt; c-&gt;V[y]; c-&gt;V[x] -= c-&gt;V[y]; c-&gt;V[0xF] = b; break; }
                case 0x6: { uint8_t b = c-&gt;V[x] & 1; c-&gt;V[x] &gt;&gt;= 1; c-&gt;V[0xF] = b; break; }
                case 0x7: { uint8_t b = c-&gt;V[y] &gt; c-&gt;V[x]; c-&gt;V[x] = c-&gt;V[y] - c-&gt;V[x]; c-&gt;V[0xF] = b; break; }
                case 0xE: { uint8_t b = (c-&gt;V[x] &gt;&gt; 7) & 1; c-&gt;V[x] &lt;&lt;= 1; c-&gt;V[0xF] = b; break; }
                default: fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        case 0xA000: c-&gt;I = nnn; break;
        case 0xB000: c-&gt;pc = nnn + c-&gt;V[0]; break;
        case 0xC000: c-&gt;V[x] = (rand() % 256) & kk; break;

        case 0xD000: {
            uint8_t vx = c-&gt;V[x] % DISPLAY_W, vy = c-&gt;V[y] % DISPLAY_H;
            c-&gt;V[0xF] = 0;
            for (int row = 0; row &lt; n; row++) {
                uint8_t sb = c-&gt;memory[c-&gt;I + row];
                for (int bit = 0; bit &lt; 8; bit++) {
                    if (!(sb & (0x80 &gt;&gt; bit))) continue;
                    int px = (vx + bit) % DISPLAY_W, py = (vy + row) % DISPLAY_H;
                    int idx = py * DISPLAY_W + px;
                    if (c-&gt;display[idx]) c-&gt;V[0xF] = 1;
                    c-&gt;display[idx] ^= 1;
                }
            }
            c-&gt;draw_flag = 1;
            break;
        }

        case 0xE000:
            if (kk == 0x9E) { if (c-&gt;keypad[c-&gt;V[x]])  c-&gt;pc += 2; }
            else if (kk == 0xA1) { if (!c-&gt;keypad[c-&gt;V[x]]) c-&gt;pc += 2; }
            else fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            break;

        case 0xF000:
            switch (kk) {
                case 0x07: c-&gt;V[x] = c-&gt;delay_timer; break;
                case 0x15: c-&gt;delay_timer = c-&gt;V[x]; break;
                case 0x18: c-&gt;sound_timer = c-&gt;V[x]; break;
                case 0x29: c-&gt;I = 0x050 + (c-&gt;V[x] * 5); break;
                case 0x0A: {
                    int pressed = -1;
                    for (int k = 0; k &lt; 16; k++) if (c-&gt;keypad[k]) { pressed = k; break; }
                    if (pressed &lt; 0) c-&gt;pc -= 2; // block: repeat this instruction
                    else c-&gt;V[x] = (uint8_t)pressed;
                    break;
                }
                default: fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
            }
            break;

        default:
            fprintf(stderr, "Unknown opcode: 0x%04X\n", opcode);
    }
}

